//! Port of upstream `test/ast-chunking.test.ts` (P6.2) — AST-aware
//! `auto` chunk strategy end to end against real tree-sitter grammars,
//! plus the `ast_chunk_golden.json` replay of upstream
//! `chunkDocumentAsync` output (generated by
//! `scripts/gen_ast_golden.ts`).
//!
//! Upstream coverage map (12 cases):
//! - `mergeBreakPoints` (2) — ported from P2 in `tests/chunking.rs`
//!   (`merge_break_points_keeps_highest_score_at_each_position` /
//!   `merge_break_points_returns_sorted_by_position` /
//!   `merge_break_points_ast_chunking_suite_case`).
//! - `AST vs Regex chunking` (5) — this file (`mod ast_vs_regex`).
//! - `chunkDocumentWithBreakPoints equivalence` (1) — `tests/chunking.rs`
//!   `chunk_document_with_break_points_equivalent_to_chunk_document`.
//! - `AST break point scores` (4) — this file (`mod scores`).
//!
//! Upstream's `getASTBreakPoints` is async-wrapped web-tree-sitter;
//! `ast_break_points` is the synchronous port — assertions are
//! identical.

#![allow(
    unused_crate_dependencies,
    reason = "each test binary only uses a subset of the package deps"
)]
#![allow(
    clippy::tests_outside_test_module,
    clippy::shadow_unrelated,
    clippy::field_reassign_with_default,
    clippy::float_cmp,
    clippy::doc_markdown,
    clippy::indexing_slicing,
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::missing_assert_message,
    clippy::panic,
    reason = "idiomatic test-code patterns"
)]

// Every case exercises `ChunkStrategy::Auto` merging — meaningless
// without the `ast` feature (`Auto` degrades to `Regex`), so the whole
// suite is feature-gated.
#[cfg(feature = "ast")]
mod ast_chunking {
    use qmd::chunk::ast::ast_break_points;
    use qmd::{
        CharChunkOptions, Chunk, ChunkStrategy, chunk_document, chunk_document_with_strategy,
        utf16_len,
    };

    /// The 30-function TypeScript corpus — verbatim shape from
    /// ast-chunking.test.ts:61-82 (`parts.join("\n")`). ASCII, so byte
    /// offsets equal the UTF-16 `pos` units the chunks report.
    fn large_ts() -> String {
        (0..30)
            .map(|i| {
                format!(
                    "
export function handler{i}(req: Request, res: Response): void {{
  const startTime = Date.now();
  const userId = req.params.userId;
  const sessionToken = req.headers.authorization;

  if (!userId || !sessionToken) {{
    res.status(400).json({{ error: \"Missing required parameters\" }});
    return;
  }}

  console.log(`Processing request {i} for user ${{userId}}`);
  const result = processBusinessLogic{i}(userId, sessionToken);

  const elapsed = Date.now() - startTime;
  res.json({{ data: result, processingTimeMs: elapsed }});
}}
"
                )
            })
            .collect::<Vec<_>>()
            .join("\n")
    }

    /// `countSplitFunctions` (ast-chunking.test.ts:84-101): how many of
    /// the 30 functions are covered by more than one chunk.
    fn count_split_functions(content: &str, chunks: &[Chunk<'_>]) -> usize {
        let mut splits = 0;
        for i in 0..30 {
            let marker = format!("function handler{i}(");
            let Some(func_start) = content.find(&marker) else {
                continue;
            };
            let next = format!("function handler{}(", i + 1);
            let func_end = content[func_start + 1..]
                .find(&next)
                .map_or_else(|| utf16_len(content), |o| func_start + 1 + o);
            let chunk_indices: std::collections::HashSet<usize> = chunks
                .iter()
                .enumerate()
                .filter(|(_, c)| {
                    let chunk_end = c.pos + utf16_len(c.text);
                    c.pos < func_end && chunk_end > func_start
                })
                .map(|(ci, _)| ci)
                .collect();
            if chunk_indices.len() > 1 {
                splits += 1;
            }
        }
        splits
    }

    mod ast_vs_regex {
        use super::*;

        /// ast-chunking.test.ts:103-111.
        #[test]
        fn ast_splits_fewer_functions_across_chunk_boundaries_than_regex() {
            let content = large_ts();
            let regex_chunks = chunk_document(&content, &CharChunkOptions::default());
            let ast_chunks = chunk_document_with_strategy(
                &content,
                Some("handlers.ts"),
                ChunkStrategy::Auto,
                &CharChunkOptions::default(),
            );

            let regex_splits = count_split_functions(&content, &regex_chunks);
            let ast_splits = count_split_functions(&content, &ast_chunks);
            assert!(ast_splits <= regex_splits, "{ast_splits} <= {regex_splits}");
        }

        /// ast-chunking.test.ts:113-128.
        #[test]
        fn markdown_files_produce_identical_chunks_in_auto_vs_regex() {
            let large_md = (0..15)
                .map(|i| {
                    format!(
                        "# Section {i}\n\n{}\n",
                        "Lorem ipsum dolor sit amet. ".repeat(40)
                    )
                })
                .collect::<Vec<_>>()
                .join("\n");

            let md_regex = chunk_document(&large_md, &CharChunkOptions::default());
            let md_ast = chunk_document_with_strategy(
                &large_md,
                Some("readme.md"),
                ChunkStrategy::Auto,
                &CharChunkOptions::default(),
            );

            assert_eq!(md_ast.len(), md_regex.len());
            for (a, r) in md_ast.iter().zip(&md_regex) {
                assert_eq!(a.text, r.text);
                assert_eq!(a.pos, r.pos);
            }
        }

        /// ast-chunking.test.ts:130-138.
        #[test]
        fn regex_strategy_bypasses_ast_entirely() {
            let content = large_ts();
            let regex_only = chunk_document_with_strategy(
                &content,
                Some("handlers.ts"),
                ChunkStrategy::Regex,
                &CharChunkOptions::default(),
            );
            let sync_regex = chunk_document(&content, &CharChunkOptions::default());

            assert_eq!(regex_only.len(), sync_regex.len());
            for (a, r) in regex_only.iter().zip(&sync_regex) {
                assert_eq!(a.text, r.text);
            }
        }

        /// ast-chunking.test.ts:140-144.
        #[test]
        fn no_filepath_falls_back_to_regex() {
            let content = large_ts();
            let no_path = chunk_document_with_strategy(
                &content,
                None,
                ChunkStrategy::Auto,
                &CharChunkOptions::default(),
            );
            let sync_regex = chunk_document(&content, &CharChunkOptions::default());
            assert_eq!(no_path.len(), sync_regex.len());
        }

        /// ast-chunking.test.ts:146-149.
        #[test]
        fn small_file_produces_single_chunk() {
            let chunks = chunk_document_with_strategy(
                "export const x = 1;",
                Some("s.ts"),
                ChunkStrategy::Auto,
                &CharChunkOptions::default(),
            );
            assert_eq!(chunks.len(), 1);
        }
    }

    mod scores {
        use super::*;

        /// ast-chunking.test.ts:175-180.
        #[test]
        fn ts_export_scores_90() {
            let code = "export class Foo {}\nexport function bar() {}";
            let points = ast_break_points(code, "a.ts");
            let export = points.iter().find(|p| p.kind == "ast:export");
            assert_eq!(export.map(|p| p.score), Some(90));
        }

        /// ast-chunking.test.ts:182-187.
        #[test]
        fn python_class_scores_100() {
            let code = "class Foo:\n    pass\n\ndef bar():\n    pass";
            let points = ast_break_points(code, "a.py");
            assert_eq!(
                points
                    .iter()
                    .find(|p| p.kind == "ast:class")
                    .map(|p| p.score),
                Some(100)
            );
        }

        /// ast-chunking.test.ts:189-194.
        #[test]
        fn go_type_scores_80() {
            let code = "package main\n\ntype Server struct {\n    port int\n}\n\nfunc main() {}";
            let points = ast_break_points(code, "a.go");
            assert_eq!(
                points
                    .iter()
                    .find(|p| p.kind == "ast:type")
                    .map(|p| p.score),
                Some(80)
            );
        }

        /// ast-chunking.test.ts:196-198.
        #[test]
        fn rust_enum_scores_80() {
            let code = "enum State {\n    On,\n    Off,\n}\n\nfn main() {}";
            let points = ast_break_points(code, "a.rs");
            assert_eq!(
                points
                    .iter()
                    .find(|p| p.kind == "ast:enum")
                    .map(|p| p.score),
                Some(80)
            );
        }
    }

    /// Golden replay — `chunk_document_with_strategy` byte-identical to
    /// upstream `chunkDocumentAsync` for every recorded
    /// `{path, strategy}` (fixture generated by
    /// `scripts/gen_ast_golden.ts`).
    #[test]
    fn ast_chunk_golden_replay() {
        let fixture = include_str!("fixtures/ast_chunk_golden.json");
        let root: serde_json::Value = serde_json::from_str(fixture).unwrap();
        let cases = root["cases"].as_array().unwrap();
        assert_eq!(cases.len(), 11);
        for case in cases {
            let path = case["path"].as_str().unwrap();
            let content = case["content"].as_str().unwrap();
            let strategy = match case["strategy"].as_str().unwrap() {
                "auto" => ChunkStrategy::Auto,
                "regex" => ChunkStrategy::Regex,
                other => panic!("unknown strategy {other}"),
            };
            let recorded = case["chunks"].as_array().unwrap();
            let got = chunk_document_with_strategy(
                content,
                Some(path),
                strategy,
                &CharChunkOptions::default(),
            );
            assert_eq!(got.len(), recorded.len(), "{path} {strategy:?} count");
            for (g, r) in got.iter().zip(recorded) {
                assert_eq!(
                    g.pos,
                    usize::try_from(r["pos"].as_u64().unwrap()).unwrap(),
                    "{path} {strategy:?} pos"
                );
                assert_eq!(
                    g.text,
                    r["text"].as_str().unwrap(),
                    "{path} {strategy:?} text @ {}",
                    r["pos"]
                );
            }
        }

        // Markdown / unknown-extension `auto` == `regex` == recorded:
        // pairing the two strategies on those paths must give the same
        // chunk set (upstream's fallback branch taken).
        for pair in ["docs/readme.md", "data/notes.xyz"] {
            let auto_case = cases
                .iter()
                .find(|c| c["path"] == pair && c["strategy"] == "auto")
                .unwrap();
            let regex_case = cases
                .iter()
                .find(|c| c["path"] == pair && c["strategy"] == "regex")
                .unwrap();
            assert_eq!(
                auto_case["chunks"], regex_case["chunks"],
                "{pair}: recorded auto must equal recorded regex"
            );
        }
    }
}
